import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {wrapTextWithCommitLink} from './wrap-text-with-commit-link'

export type DeploymentTitleResult = {
  /** HTML content for the title (may contain embedded anchors when autolinks are present) */
  titleHtml: string
  /** Commit URL — provided only when ListItemTitle should handle the link (no embedded autolinks) */
  href?: string
}

export function useDeploymentTitle(name: string | undefined, commitUrl: string): DeploymentTitleResult {
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const autolinkFixEnabled = useFeatureFlag('deployments_commit_message_autolink_fix')
  const nameHtml = name ?? ''
  if (autolinkFixEnabled) {
    // Autolink path: HTML may contain existing <a> tags, so we embed all anchors in the HTML
    // and don't pass href to ListItemTitle (to avoid nested <a> elements)
    return {titleHtml: wrapTextWithCommitLink(nameHtml, commitUrl), href: undefined}
  }
  // Simple path: return raw name HTML and let ListItemTitle handle the link via HeadingLink
  return {titleHtml: nameHtml, href: commitUrl}
}
